package com.example.rokidgeminisecretary;
import android.content.*;import android.graphics.*;import android.util.Base64;import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;
public final class PhotoFollowUpChecks {
 static int n;static void ok(boolean b){n++;if(!b)throw new AssertionError("photo follow-up "+n);}interface Work{void run()throws Exception;}static void rejects(Work w)throws Exception{boolean failed=false;try{w.run();}catch(Exception e){failed=true;}ok(failed);}
 static JSONObject record(JSONObject payload)throws Exception{return new JSONObject().put("route","image-question").put("payload",payload);}
 public static int run(Context base)throws Exception{n=0;Context c=new ContextWrapper(base){public File getFilesDir(){File f=new File(base.getFilesDir(),"photo-followup");f.mkdirs();return f;}};
  Bitmap b=Bitmap.createBitmap(32,24,Bitmap.Config.ARGB_8888);b.eraseColor(Color.BLUE);ByteArrayOutputStream bytes=new ByteArrayOutputStream();b.compress(Bitmap.CompressFormat.JPEG,80,bytes);b.recycle();String image=Base64.encodeToString(bytes.toByteArray(),Base64.NO_WRAP);
  JSONObject original=new JSONObject().put("requestId","synthetic-photo-original").put("message","original question").put("image",image).put("imageCount",1).put("kinds",new JSONArray().put("image"));String frozen=original.toString();
  JSONObject prepared=PhotoFollowUp.prepare(record(original),"右上は？");ok(prepared.getString("message").equals("右上は？"));ok(prepared.getString("image").equals(image));ok(prepared.getInt("imageCount")==1);ok(!prepared.has("requestId"));ok(!prepared.has("parent"));ok(!prepared.has("referenceKey"));ok(original.toString().equals(frozen));ok(PhotoFollowUp.prepare(record(original),"").getString("message").isEmpty());
  JSONObject multi=new JSONObject(original.toString()).put("imageCount",2).put("kinds",new JSONArray().put("image").put("unknown"));ok(PhotoFollowUp.prepare(record(multi),"この文字を訳して").getJSONArray("kinds").length()==2);
  rejects(()->PhotoFollowUp.prepare(null,""));rejects(()->PhotoFollowUp.prepare(record(original).put("route","media-generate"),""));rejects(()->PhotoFollowUp.prepare(record(new JSONObject(original.toString()).put("parent","wrong")),""));rejects(()->PhotoFollowUp.prepare(record(new JSONObject(original.toString()).put("referenceKey","wrong")),""));rejects(()->PhotoFollowUp.prepare(record(new JSONObject(original.toString()).put("image","")),""));rejects(()->PhotoFollowUp.prepare(record(new JSONObject(original.toString()).put("image","a".repeat(800001))),""));rejects(()->PhotoFollowUp.prepare(record(new JSONObject(original.toString()).put("image","%%%")),""));rejects(()->PhotoFollowUp.prepare(record(new JSONObject(original.toString()).put("image",Base64.encodeToString(new byte[]{1,2,3},Base64.NO_WRAP))),""));rejects(()->PhotoFollowUp.prepare(record(new JSONObject(original.toString()).put("kinds",new JSONArray().put("video"))),""));rejects(()->PhotoFollowUp.prepare(record(new JSONObject(original.toString()).put("imageCount",7)),""));rejects(()->PhotoFollowUp.prepare(record(new JSONObject(multi.toString()).put("kinds",new JSONArray().put("image"))),""));rejects(()->PhotoFollowUp.prepare(record(original),"x".repeat(2401)));rejects(()->PhotoFollowUp.prepare(record(original),"__LOKI_IMAGE__:wrong"));
  String id="a".repeat(64),other="b".repeat(64);ConversationRecoveryStore.save(c,id,"image-question",original);ConversationRecoveryStore.save(c,other,"send",new JSONObject().put("requestId","synthetic-text-original").put("message","text only"));
  ok(PhotoFollowUp.list(c).length()==1);ok(PhotoFollowUp.list(c).getJSONObject(0).getString("id").equals(id));ok(!PhotoFollowUp.list(c).getJSONObject(0).has("image"));String before=ConversationRecoveryStore.read(c,id).toString();String outbox=c.getSharedPreferences("loki_web_console",0).getString("outbox","[]");ok(PhotoFollowUp.read(c,id,"この文字を訳して").getString("message").equals("この文字を訳して"));ok(PhotoFollowUp.read(c,id,"右上は？").getString("image").equals(image));ok(ConversationRecoveryStore.read(c,id).toString().equals(before));ok(c.getSharedPreferences("loki_web_console",0).getString("outbox","[]").equals(outbox));rejects(()->PhotoFollowUp.read(c,"../escape",""));
  File stored=ConversationRecoveryStore.file(c,id);byte[] cipher=java.nio.file.Files.readAllBytes(stored.toPath());ok(!new String(cipher,StandardCharsets.UTF_8).contains("original question"));JSONObject expired=ConversationRecoveryStore.read(c,id).put("at",System.currentTimeMillis()-ConversationRecoveryStore.TTL);java.nio.file.Files.write(stored.toPath(),DeviceSecrets.photos().encrypt(expired.toString().getBytes(StandardCharsets.UTF_8)));rejects(()->PhotoFollowUp.read(c,id,""));ok(PhotoFollowUp.list(c).length()==0);return n;
 }
}
